CREATE TABLE IF NOT EXISTS library_likutey_halajot_fine_zones_v1 (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), document_id UUID NOT NULL REFERENCES library_documents(id), pdf_page INTEGER NOT NULL, page_anchor_id UUID NOT NULL REFERENCES library_page_anchors_v2(page_anchor_id), source_run_id TEXT NOT NULL, structural_detector_run_id TEXT NOT NULL, fine_zone_run_id TEXT NOT NULL, zone_type TEXT NOT NULL, zone_role TEXT NOT NULL, authority_level TEXT NOT NULL, marker_kind TEXT, marker_value TEXT, source_or_commentator TEXT, visible_note_number TEXT, text_quote TEXT NOT NULL, char_start INTEGER NOT NULL, char_end INTEGER NOT NULL, quote_hash TEXT NOT NULL, confidence NUMERIC NOT NULL, evidence_origin TEXT NOT NULL, detection_origin TEXT NOT NULL, validation_status TEXT NOT NULL, review_status TEXT NOT NULL, warnings JSONB NOT NULL DEFAULT '[]'::jsonb, raw_detection JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(fine_zone_run_id,page_anchor_id,zone_type,char_start,char_end));
CREATE INDEX IF NOT EXISTS idx_lh_fine_zones_type ON library_likutey_halajot_fine_zones_v1(zone_type,pdf_page);
CREATE OR REPLACE VIEW library_likutey_halajot_search_ready_v4 AS
SELECT s.*,z.zone_type AS fine_zone_type,z.zone_role AS fine_zone_role,z.marker_kind AS fine_marker_kind,z.marker_value AS fine_marker_value,z.source_or_commentator,z.visible_note_number AS fine_visible_note_number,z.text_quote,z.confidence AS fine_zone_confidence,z.validation_status AS fine_validation_status,z.review_status AS fine_review_status
FROM library_likutey_halajot_search_ready_v2 s LEFT JOIN library_likutey_halajot_fine_zones_v1 z ON z.page_anchor_id=(SELECT page_anchor_id FROM library_page_anchors_v2 a WHERE a.document_id=s.document_id AND a.pdf_page_number=s.pdf_page AND a.edition_id='likutey_halajot_page_first_v1');
